<script>const rows=[...document.querySelectorAll('.recipient')],search=document.getElementById('candidateSearch'),boxes=[...document.querySelectorAll('.recipient input[type="checkbox"]')],summary=document.getElementById('recipientSummary');function updateSummary(){summary.textContent=boxes.filter(box=>box.checked).length+' selected'}search.oninput=()=>{const query=search.value.trim().toLowerCase();rows.forEach(row=>row.classList.toggle('hide',query&&!row.dataset.find.includes(query)))};boxes.forEach(box=>box.addEventListener('change',updateSummary));updateSummary();</script>
